AOS.init({duration:700,once:true});

(function(){
  // Theme toggle with icon swap
  const themeBtn=document.getElementById("theme-toggle");
  if(themeBtn){
    const icon=themeBtn.querySelector("i");
    const prefersDark=window.matchMedia&&window.matchMedia("(prefers-color-scheme: dark)").matches;
    const saved=localStorage.getItem("theme");
    if(saved==="dark"||(!saved&&prefersDark)){
      document.body.classList.add("dark-theme");
      if(icon){icon.classList.remove("fa-moon");icon.classList.add("fa-sun");}
    }
    themeBtn.addEventListener("click",()=>{
      const isDark=document.body.classList.toggle("dark-theme");
      localStorage.setItem("theme",isDark?"dark":"light");
      if(icon){
        icon.classList.toggle("fa-moon",!isDark);
        icon.classList.toggle("fa-sun",isDark);
      }
    });
  }

  // Smooth scroll for nav links
  document.querySelectorAll('a.nav-link[href^="#"]').forEach(link=>{
    link.addEventListener("click",function(e){
      e.preventDefault();
      const target=document.querySelector(this.getAttribute("href"));
      if(target) target.scrollIntoView({behavior:"smooth",block:"start"});
      // Close mobile nav
      const navCollapse=document.querySelector(".navbar-collapse.show");
      if(navCollapse) bootstrap.Collapse.getInstance(navCollapse)?.hide();
    });
  });

  // Dynamic year in footer
  const yearEl=document.getElementById("current-year");
  if(yearEl) yearEl.textContent=new Date().getFullYear();

  // Image fallback
  (function(){
    const fallback="image/fto.jpg";
    document.querySelectorAll("img").forEach(img=>{
      img.addEventListener("error",()=>{
        if(img.src&&!img.dataset.fallbackApplied){
          img.dataset.fallbackApplied="1";
          img.src=fallback;
          img.classList.add("img-fallback");
        }
      });
      if(img.complete&&img.naturalWidth===0) img.dispatchEvent(new Event("error"));
    });
  })();

  // Scroll progress bar
  const progressBar=document.getElementById("scroll-progress");
  if(progressBar){
    window.addEventListener("scroll",()=>{
      const scrollTop=window.scrollY;
      const docHeight=document.documentElement.scrollHeight-window.innerHeight;
      const scrollPercent=(scrollTop/docHeight)*100;
      progressBar.style.width=scrollPercent+"%";
    });
  }

  // Scroll-to-top button
  const scrollToTopBtn=document.getElementById("scrollToTop");
  if(scrollToTopBtn){
    window.addEventListener("scroll",()=>{
      if(window.scrollY>400){
        scrollToTopBtn.classList.add("visible");
      }else{
        scrollToTopBtn.classList.remove("visible");
      }
    });
    scrollToTopBtn.addEventListener("click",()=>{
      window.scrollTo({top:0,behavior:"smooth"});
    });
  }

  // Navbar scroll effect
  const navbar=document.querySelector(".navbar");
  if(navbar){
    window.addEventListener("scroll",()=>{
      if(window.scrollY>50){
        navbar.classList.add("scrolled");
      }else{
        navbar.classList.remove("scrolled");
      }
    });
  }

  // Active nav link on scroll
  const sections=document.querySelectorAll("section[id]");
  const navLinks=document.querySelectorAll(".nav-link[href^='#']");
  window.addEventListener("scroll",()=>{
    let current="";
    sections.forEach(section=>{
      const sectionTop=section.offsetTop-100;
      if(window.scrollY>=sectionTop){
        current=section.getAttribute("id");
      }
    });
    navLinks.forEach(link=>{
      link.classList.remove("active");
      if(link.getAttribute("href")==="#"+current){
        link.classList.add("active");
      }
    });
  });

  // Typing effect
  const typingEl=document.getElementById("typing-text");
  if(typingEl){
    const phrases=[
      "Analista de Sistemas — BIOS",
      "Desarrollador Backend .NET & Java",
      "Creando APIs REST escalables",
      "Apps móviles con Flutter"
    ];
    let phraseIdx=0,charIdx=0,isDeleting=false;
    function type(){
      const current=phrases[phraseIdx];
      if(isDeleting){
        typingEl.textContent=current.substring(0,charIdx-1);
        charIdx--;
      }else{
        typingEl.textContent=current.substring(0,charIdx+1);
        charIdx++;
      }
      let delay=isDeleting?40:80;
      if(!isDeleting&&charIdx===current.length){
        delay=2000;
        isDeleting=true;
      }else if(isDeleting&&charIdx===0){
        isDeleting=false;
        phraseIdx=(phraseIdx+1)%phrases.length;
        delay=400;
      }
      setTimeout(type,delay);
    }
    type();
  }
})();
